class Solution:
    def isRectangleCover(self, rectangles):
        n = len(rectangles)
        minX = min(r[0] for r in rectangles)
        minY = min(r[1] for r in rectangles)
        maxX = max(r[2] for r in rectangles)
        maxY = max(r[3] for r in rectangles)
        total = 0
        for i in range(n):
            x1, y1, x2, y2 = rectangles[i]
            total += (x2 - x1) * (y2 - y1)
            for j in range(i + 1, n):
                a1, b1, a2, b2 = rectangles[j]
                if min(x2, a2) > max(x1, a1) and min(y2, b2) > max(y1, b1):
                    return False
        return total == (maxX - minX) * (maxY - minY)

