class Solution {
    public boolean isRectangleCover(int[][] rectangles) {
        Set<Long> corners = new HashSet<>();
        long area = 0;
        long minX = Long.MAX_VALUE, minY = Long.MAX_VALUE, maxX = Long.MIN_VALUE, maxY = Long.MIN_VALUE;
        for (int[] r : rectangles) {
            long x1 = r[0], y1 = r[1], x2 = r[2], y2 = r[3];
            minX = Math.min(minX, x1); minY = Math.min(minY, y1);
            maxX = Math.max(maxX, x2); maxY = Math.max(maxY, y2);
            area += (x2 - x1) * (y2 - y1);
            long[] ps = {encode(x1, y1), encode(x1, y2), encode(x2, y1), encode(x2, y2)};
            for (long p : ps) {
                if (!corners.add(p)) corners.remove(p);
            }
        }
        if (corners.size() != 4) return false;
        long[] expected = {encode(minX, minY), encode(minX, maxY), encode(maxX, minY), encode(maxX, maxY)};
        for (long p : expected) if (!corners.contains(p)) return false;
        return area == (maxX - minX) * (maxY - minY);
    }
    private long encode(long x, long y) {
        return (x + 100000L) * 200001L + (y + 100000L);
    }
}

