class Solution:
    def isRectangleCover(self, rectangles):
        events = []
        for x1, y1, x2, y2 in rectangles:
            events.append((x1, 1, y1, y2))
            events.append((x2, -1, y1, y2))
        events.sort()
        active = []
        prev_x = None
        prev_len = None
        i = 0
        n = len(events)
        while i < n:
            x = events[i][0]
            if prev_x is not None:
                merged = self.merge(active)
                if len(merged) != 1:
                    return False
                cur_len = merged[0][1] - merged[0][0]
                if prev_len is not None and cur_len != prev_len:
                    return False
                prev_len = cur_len
            while i < n and events[i][0] == x:
                _, t, y1, y2 = events[i]
                if t == 1:
                    active.append((y1, y2))
                else:
                    active.remove((y1, y2))
                i += 1
            prev_x = x
        return True

    def merge(self, ivs):
        ivs = sorted(ivs)
        res = []
        for s, e in ivs:
            if res and s < res[-1][1]:
                return [(0, 0), (0, 0)]
            if res and s == res[-1][1]:
                res[-1] = (res[-1][0], e)
            else:
                res.append((s, e))
        return res

