        long long prevLen = -1;
        while (i < n) {
            long long x = events[i][0];
            if (!active.empty()) {
                long long lo = LLONG_MAX, hi = LLONG_MIN, cnt = 0;
                long long lastEnd = LLONG_MIN;
                for (auto& iv : active) {
                    if (iv.first < lastEnd) return false;
                    if (iv.first == lastEnd) { /* contiguous */ }
                    else cnt++;
                    lo = min(lo, iv.first); hi = max(hi, iv.second);
                    lastEnd = iv.second;
                }
                if (cnt != 1) return false;
                if (prevLen != -1 && hi - lo != prevLen) return false;
                prevLen = hi - lo;
            }
            while (i < n && events[i][0] == x) {
                auto& e = events[i++];
                pair<long long,long long> iv = {e[2], e[3]};
                if (e[1] == 1) active.insert(iv);
                else active.erase(active.find(iv));
            }
        }
        return true;
    }
};

