var isRectangleCover = function(rectangles) {
    const events = [];
    for (const [x1, y1, x2, y2] of rectangles) {
        events.push([x1, 1, y1, y2]);
        events.push([x2, -1, y1, y2]);
    }
    events.sort((a, b) => a[0] - b[0]);
    let active = [];
    let prevLen = null;
    let i = 0;
    while (i < events.length) {
        const x = events[i][0];
        if (active.length > 0) {
            const sorted = [...active].sort((a, b) => a[0] - b[0]);
            let blocks = 0, lastEnd = -Infinity;
            for (const [s, e] of sorted) {
                if (s < lastEnd) return false;
                if (s > lastEnd) blocks++;
                lastEnd = Math.max(lastEnd, e);
            }
            if (blocks !== 1) return false;
            const len = lastEnd - sorted[0][0];
            if (prevLen !== null && len !== prevLen) return false;
            prevLen = len;
        }
        while (i < events.length && events[i][0] === x) {
            const [, t, y1, y2] = events[i++];
            if (t === 1) active.push([y1, y2]);
            else active.splice(active.findIndex(p => p[0] === y1 && p[1] === y2), 1);
        }
    }
    return true;
};
